using System;
using System.Security.Cryptography;
using System.Text;

public class AesGcmEncryption
{
    public static (byte[] ciphertext, byte[] nonce, byte[] tag) Encrypt(byte[] plaintext, byte[] key)
    {
        byte[] nonce = new byte[AesGcm.NonceByteSizes.MaxSize]; // 12 bytes
        RandomNumberGenerator.Fill(nonce);

        byte[] tag = new byte[AesGcm.TagByteSizes.MaxSize]; // 16 bytes
        byte[] ciphertext = new byte[plaintext.Length];

        using var aes = new AesGcm(key, AesGcm.TagByteSizes.MaxSize);
        aes.Encrypt(nonce, plaintext, ciphertext, tag);

        return (ciphertext, nonce, tag);
    }

    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] nonce, byte[] tag)
    {
        byte[] plaintext = new byte[ciphertext.Length];
        using var aes = new AesGcm(key, AesGcm.TagByteSizes.MaxSize);
        aes.Decrypt(nonce, ciphertext, tag, plaintext);
        return plaintext;
    }
}

public class Program
{
    public static void Main()
    {
        byte[] key = new byte[32];
        RandomNumberGenerator.Fill(key);

        string secretData = "NOMOR KARTU KREDIT: 4111-2222-3333-4444";
        byte[] plainBytes = Encoding.UTF8.GetBytes(secretData);

        var (ciphertext, nonce, tag) = AesGcmEncryption.Encrypt(plainBytes, key);
        Console.WriteLine($"Ciphertext (Hex): {Convert.ToHexString(ciphertext)[..20]}...");
        Console.WriteLine($"Auth Tag   (Hex): {Convert.ToHexString(tag)}");

        byte[] decryptedBytes = AesGcmEncryption.Decrypt(ciphertext, key, nonce, tag);
        Console.WriteLine($"Decrypted Text  : {Encoding.UTF8.GetString(decryptedBytes)}");
    }
}
